from pathlib import Path
p=Path('/home/nostalgia/lerobot_workspace/lerobot/src/lerobot/rollout/strategies/core.py')
s=p.read_text()
bak=p.with_suffix(p.suffix+'.bak_macro_pan_scan')
if not bak.exists(): bak.write_text(s)
anchor='''            # Conservative macro values are kept within poses already observed\n            # from ACT rollout logs on this robot/checkpoint.\n            close_g = float(os.environ.get("ROLLOUT_AFTER_GRASP_CLOSE_VALUE", "3") or 3)\n'''
insert='''            scan_values_env = os.environ.get("ROLLOUT_MACRO_SCAN_PLACE_PANS", "").strip()\n            if scan_values_env:\n                scan_values = [float(x.strip()) for x in scan_values_env.split(",") if x.strip()]\n                scan_hold = int(float(os.environ.get("ROLLOUT_MACRO_SCAN_HOLD_FRAMES", "60") or 60))\n                scan_index = min(len(scan_values) - 1, frame // max(1, scan_hold))\n                scan_pan = scan_values[scan_index]\n                target = {\n                    "shoulder_pan.pos": scan_pan,\n                    "shoulder_lift.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_LIFT", "45") or 45),\n                    "elbow_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_ELBOW_FLEX", "-52") or -52),\n                    "wrist_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_WRIST_FLEX", "100") or 100),\n                    "gripper.pos": float(os.environ.get("ROLLOUT_AFTER_GRASP_OPEN_VALUE", "45") or 45),\n                }\n                phase = f"scan_pan_{scan_pan}"\n                for key, value in target.items():\n                    if key in action_dict:\n                        action_dict[key] = value\n                if os.environ.get("ROLLOUT_DEBUG_AFTER_GRASP_MACRO", "0") == "1":\n                    import time\n                    print("[AFTER GRASP MACRO]", flush=True)\n                    print(f"time={time.time():.6f}", flush=True)\n                    print(f"frame={frame}", flush=True)\n                    print(f"phase={phase}", flush=True)\n                    print(f"target={target}", flush=True)\n                # Skip the normal fixed-place macro phase table for scan mode.\n                action_log_path = os.environ.get("ROLLOUT_ACTION_LOG_PATH")\n                if action_log_path:\n                    import time as _time\n                    from pathlib import Path as _Path\n                    log_path = _Path(action_log_path)\n                    log_path.parent.mkdir(parents=True, exist_ok=True)\n                    write_header = not log_path.exists()\n                    with log_path.open("a", encoding="utf-8") as f:\n                        if write_header:\n                            f.write("t_wall," + ",".join(action_dict.keys()) + "\\n")\n                        f.write(str(_time.time()) + "," + ",".join(str(action_dict[k]) for k in action_dict.keys()) + "\\n")\n                processed = ctx.processors.robot_action_processor((action_dict, obs_raw))\n                ctx.hardware.robot_wrapper.send_action(processed)\n                return action_dict\n\n'''
if anchor not in s: raise SystemExit('scan anchor not found')
s=s.replace(anchor, insert+anchor,1)
p.write_text(s)
print('patched macro pan scan')
